def generate(seed):
    r = random.Random(seed)
    T = list('ABCDE')
    r.shuffle(T)
    T = ''.join(T)

    def sat(w, t):
        i = w.index(t[0])
        if t[1] == '<':
            return i < w.index(t[2])
        if t[1] == '|':
            return abs(i - w.index(t[2])) == 1
        return i == int(t[2]) - 1

    pool = []
    for a, b in itertools.permutations('ABCDE', 2):
        pool.append(a + '<' + b)
        if a < b:
            pool.append(a + '|' + b)
    for a in 'ABCDE':
        for k in '12345':
            pool.append(a + '#' + k)
    pool = [t for t in pool if sat(T, t)]
    r.shuffle(pool)
    hard = [t for t in pool if t[1] == '#']
    cap = r.randint(1, 2)
    keep = hard[:cap]
    pool = [t for t in pool if t[1] != '#' or t in keep] + hard[cap:]
    cands = [''.join(p) for p in itertools.permutations('ABCDE')]
    out = []
    for t in pool:
        nc = [w for w in cands if sat(w, t)]
        if len(nc) < len(cands):
            out.append(t)
            cands = nc
        if len(cands) == 1:
            break
    r.shuffle(out)
    return ' '.join(out)

