def solve(clue):
    C = clue.split()

    def sat(w, t):
        i = w.index(t[0])
        if t[1] == '<':
            return i < w.index(t[2])
        if t[1] == '|':
            return abs(i - w.index(t[2])) == 1
        return i == int(t[2]) - 1

    for p in itertools.permutations('ABCDE'):
        w = ''.join(p)
        if all(sat(w, t) for t in C):
            return w
    return ''

